CREATE TABLE IF NOT EXISTS ldw_tenants(id uuid PRIMARY KEY,name varchar(180) NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS ldw_users(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ldw_tenants(id),email varchar(254) NOT NULL,password_hash text NOT NULL,role varchar(20) NOT NULL CHECK(role IN ('admin','author','client','legal','technical','approver','homologator')),verified boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now(),UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS ldw_sessions(token_hash char(64) PRIMARY KEY,csrf_hash char(64) NOT NULL,user_id uuid NOT NULL REFERENCES ldw_users(id),expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS ldw_sessions_expiry ON ldw_sessions(expires_at);
CREATE TABLE IF NOT EXISTS ldw_docs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ldw_tenants(id),created_by uuid NOT NULL REFERENCES ldw_users(id),title varchar(180) NOT NULL,kind varchar(180) NOT NULL,description text NOT NULL,legal_emails jsonb NOT NULL,rounds smallint NOT NULL CHECK(rounds IN(1,2)),destination varchar(10) NOT NULL CHECK(destination IN ('SIGN','PUBLISH')),stages jsonb NOT NULL,stage_index smallint NOT NULL DEFAULT 1,revision_cycle integer NOT NULL DEFAULT 1,version integer NOT NULL DEFAULT 1,body text NOT NULL,body_hash char(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS ldw_docs_tenant ON ldw_docs(tenant_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS ldw_versions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,doc_id uuid NOT NULL REFERENCES ldw_docs(id),version integer NOT NULL,body text NOT NULL,body_hash char(64) NOT NULL,actor_id uuid NOT NULL REFERENCES ldw_users(id),created_at timestamptz DEFAULT now(),UNIQUE(doc_id,version));
CREATE TABLE IF NOT EXISTS ldw_assignments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,doc_id uuid NOT NULL REFERENCES ldw_docs(id),stage varchar(50) NOT NULL,user_id uuid NOT NULL REFERENCES ldw_users(id),assigned_by uuid NOT NULL REFERENCES ldw_users(id),created_at timestamptz DEFAULT now(),UNIQUE(doc_id,stage));
CREATE TABLE IF NOT EXISTS ldw_decisions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,doc_id uuid NOT NULL REFERENCES ldw_docs(id),stage varchar(50) NOT NULL,revision_cycle integer NOT NULL,actor_id uuid NOT NULL REFERENCES ldw_users(id),action varchar(16) NOT NULL CHECK(action IN ('APPROVE','CHANGES')),note text NOT NULL,document_hash char(64) NOT NULL,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS ldw_decisions_lookup ON ldw_decisions(tenant_id,doc_id,revision_cycle);
CREATE TABLE IF NOT EXISTS ldw_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,doc_id uuid REFERENCES ldw_docs(id),actor_id uuid NOT NULL REFERENCES ldw_users(id),kind varchar(50) NOT NULL,detail jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS ldw_events_lookup ON ldw_events(tenant_id,doc_id,created_at);
